'use strict';
// No default fault current, k coefficient or trip time is generated by the UI.
function epCableShortCircuitThermalHtmlV1(project,lineId,lookup){
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const line=Array.isArray(project?.lines)?project.lines.find(l=>l?.id===lineId):null;
 if(!line)return '<p>Выберите цепь для проверки стойкости кабеля при КЗ.</p>';
 const input=line.shortCircuitThermalInput||{};
 const formField=(name,label,value)=>'<label>'+label+'<input name="'+name+'" value="'+esc(value??'')+'"></label>';
 const select=(name,options,value)=>'<label>'+name+'<select name="'+name+'">'+
  options.map(([v,label])=>'<option value="'+esc(v)+'" '+(v===value?'selected':'')+'>'+label+'</option>').join('')+
  '</select></label>';
 let article=null;try{article=lookup?.(line.catalogSku);}catch(_){}
 const r=typeof epCableShortCircuitThermalV1==='function'?
  epCableShortCircuitThermalV1(project,line,article):null;
 const form='<form data-cable-thermal="'+esc(line.id)+'"><details data-cable-thermal-editor>'+
  '<summary>Термическая стойкость проводника при КЗ · I²t ≤ k²S²</summary>'+
  '<p>Укажите роль и материал проводника, сечение, k с температурным обоснованием, конкретный вид КЗ, ток и гарантированное максимальное время отключения. Расчёт применяется только к указанному сценарию.</p>'+
  select('thermalRole',[['PHASE','Фазный'],['NEUTRAL','Нейтральный'],['PE','Защитный PE']],input.conductorRole)+
  select('thermalMaterial',[['','Материал'],['Cu','Медь'],['Al','Алюминий']],input.conductorMaterial)+
  formField('thermalInsulation','Изоляция и температурные условия',input.insulationType)+
  formField('thermalSection','Сечение проверяемого проводника, мм²',input.sectionMm2)+
  formField('thermalK','k, А√с/мм²',input.kA_SqrtS_PerMm2)+
  select('thermalCurrentBasis',[['DECLARED_SCENARIO','Отдельно заданный ток КЗ'],['LINKED_MAXIMUM','Расчёт Ik,max (при совпадении точки и вида КЗ)']],input.currentBasis)+
  select('thermalFaultModel',[['','Выберите вид КЗ'],['THREE_PHASE_POSITIVE_SEQUENCE','Трёхфазное симметричное'],['SINGLE_PHASE_L_N','L–N'],['L_PE','L–PE (только отдельная оценка)']],input.faultModel)+
  formField('thermalPoint','Точка короткого замыкания',input.comparisonPoint)+
  formField('thermalFaultCurrent','Ток КЗ, А (для отдельного сценария)',input.faultCurrentA)+
  formField('thermalClearingTime','Максимальное время отключения, с (до 5)',input.clearingTimeS)+
  formField('thermalKSource','Источник k и начальной/конечной температуры',input.kSource)+
  formField('thermalTimeSource','Источник гарантированного времени отключения',input.timeSource)+
  formField('thermalCurrentSource','Источник тока КЗ для отдельного сценария',input.faultCurrentSource)+
  formField('thermalConductorSource','Источник характеристик проводника',input.conductorSource)+
  formField('thermalMethodSource','Основание применимости адиабатической проверки',input.methodSource)+
  '<label><input type="checkbox" name="thermalTemperatureConfirmed" '+(input.temperatureBasisConfirmed?'checked':'')+'> Температурные основания k подтверждены</label>'+
  '<label><input type="checkbox" name="thermalMethodConfirmed" '+(input.adiabaticApplicabilityConfirmed?'checked':'')+'> Условия применения адиабатического метода проверены</label>'+
  '<label><input type="checkbox" name="thermalGuaranteeConfirmed" '+(input.clearingTimeGuaranteeConfirmed?'checked':'')+'> Максимальное время относится к выбранной точке и виду КЗ</label>'+
  '<button class="btn primary" type="submit">Проверить и сохранить исходные данные</button></details></form>';
 return form+'<p>Энергия КЗ I²t: '+esc(r?.faultEnergyA2s??'не рассчитана')+
  ' А²с · стойкость k²S²: '+esc(r?.conductorCapacityA2s??'не рассчитана')+
  ' А²с · статус: '+esc(r?.numericalStatus??'UNKNOWN')+
  ' · замечания: '+esc((r?.issues||[]).map(i=>i.code).join('; '))+'</p>';
}
if(typeof module!=='undefined'&&module.exports)module.exports={epCableShortCircuitThermalHtmlV1};
